@app.cell
def _(COND_COLOR, COND_EN, CONDS, MAXK, NPROB, RUNS, V, att_at, is_pass, metric, n_cases, np, plt):
    _by_solved = metric.value.startswith("全部")
    _total_cases = sum(n_cases(p["name"]) for p in V["problems"])
    curves = {}
    for _c in CONDS:
        _m = np.zeros((RUNS, MAXK))
        for _t in V["tasks"]:
            for _k in range(1, MAXK + 1):
                _row = att_at(_t["b"][_c], _k)
                _m[_t["r"], _k - 1] += is_pass(_t["p"], _row) if _by_solved else (_row[1] + _row[2]) / _total_cases
        curves[_c] = _m
    _fig, _ax = plt.subplots(figsize=(6.4, 4.6))
    _x = np.arange(1, MAXK + 1)
    _hi = 0
    for _j, _c in enumerate(CONDS):
        _m = curves[_c]
        _dx = (_j - (len(CONDS) - 1) / 2) * 0.035  # 平均值相同的線稍微錯開，才不會互相蓋住
        _ax.fill_between(_x, _m.min(0), _m.max(0), color=COND_COLOR[_c], alpha=0.12, linewidth=0)
        _ax.plot(_x + _dx, _m.mean(0), "-o", color=COND_COLOR[_c], label=COND_EN[_c], linewidth=2.2, markersize=5)
        _hi = max(_hi, _m.max())
    _ax.set_xticks(_x)
    _ax.set_xlabel("attempt # (1 = shared first attempt)")
    if _by_solved:
        _ax.set_ylabel(f"problems passing ALL tests (of {NPROB})")
        _ax.set_ylim(0, min(NPROB, max(6, _hi + 1)))
    else:
        _ax.set_ylabel("share of test cases passed")
        _ax.set_ylim(0, 1)
    _ax.set_title(f"{V['meta']['model']}, {RUNS} runs: mean line, min-max band", fontsize=10)
    _ax.grid(alpha=0.3)
    _ax.legend(fontsize=8.5, loc="upper center", bbox_to_anchor=(0.5, -0.16), ncol=2, frameon=False)
    _fig.tight_layout()
    _fig
    return (curves,)


@app.cell
def _(COND_LABEL, CONDS, MAXK, RUNS, V, att_at, is_pass, itertools, mo):
    _failed = [t for t in V["tasks"] if not is_pass(t["p"], t["b"][CONDS[0]][0])]
    _first_ok = len(V["tasks"]) - len(_failed)
    _rows = []
    for _c in CONDS:
        _rescued = sum(is_pass(t["p"], att_at(t["b"][_c], MAXK)) for t in _failed)
        _per_run = [sum(is_pass(t["p"], att_at(t["b"][_c], MAXK)) for t in V["tasks"] if t["r"] == r)
                    for r in range(RUNS)]
        _same = _rep = 0
        for _t in V["tasks"]:
            _r = _t["b"][_c]
            for _a, _b in itertools.pairwise(_r):
                _rep += 1
                _same += _a[0] == _b[0]
        _rows.append(
            f"| {COND_LABEL[_c]} | **{_rescued}** | {min(_per_run)}–{max(_per_run)} | "
            f"{_same}/{_rep}" + (f"（{_same / _rep:.0%}）" if _rep else "") + " |"
        )
    _table = "\n    ".join(_rows)
    mo.md(
        f"""
    第 1 版：{len(V["tasks"])} 個題次（12 題 × {RUNS} 次重跑）只有 **{_first_ok}** 個全過，剩下 **{len(_failed)}** 個交給各種下一步：

    | 下一步 | 救回幾個（共 {len(_failed)} 個） | 每輪 12 題最後全過（最少–最多） | 新版與上一版**一字不差** |
    |---|---|---|---|
    {_table}

    最後一欄最值得看：同一段對話裡，小模型很常把**上一版原封不動再交一次**——
    它「看得見」錯誤訊息，卻沒有拿它去改程式。（上圖可以切換成「通過的測試案例比例」，看部分進步。）
    """
    )
    return


