@app.cell
def _(PROB, V, difflib, html, mo, trace_cond, trace_prob, trace_run):
    _p = PROB[trace_prob.value]
    _t = next(t for t in V["tasks"] if t["p"] == trace_prob.value and t["r"] == trace_run.value)
    _rows = _t["b"][trace_cond.value]
    _nb, _ne = len(_p["basic"]), len(_p["edge"])

    def _dots(row):
        # 每個圓點＝一個測試案例（依題目的測試順序）：實心＝基本、空心＝邊界；綠過紅沒過
        _b = V["bits"][row[0]] or [0] * (_nb + _ne)
        _s = "".join(
            f'<span title="basic {i + 1}" style="display:inline-block;width:11px;height:11px;border-radius:50%;'
            f'margin:0 2px;background:{"#55A868" if _b[i] else "#C44E52"}"></span>' for i in range(_nb))
        _s += "&nbsp;"
        _s += "".join(
            f'<span title="edge {i + 1}" style="display:inline-block;width:11px;height:11px;border-radius:50%;'
            f'margin:0 2px;border:2px solid {"#55A868" if _b[_nb + i] else "#C44E52"};box-sizing:border-box"></span>'
            for i in range(_ne))
        return _s

    def _pre(text, border):
        return (f'<pre style="white-space:pre-wrap;font-size:12px;line-height:1.5;margin:6px 0;padding:8px 10px;'
                f'border-left:4px solid {border};background:rgba(127,127,127,.07);border-radius:0 8px 8px 0">'
                f"{html.escape(text)}</pre>")

    def _diff(a, b):
        if a == b:
            return ('<div style="font-size:12.5px;font-weight:700;color:#C44E52;margin:4px 0">'
                    "↺ 跟上一版一字不差——它把同一份程式又交了一次</div>")
        _lines = list(difflib.unified_diff(a.splitlines(), b.splitlines(), lineterm="", n=1))[2:]
        _out = []
        for _ln in _lines[:40]:
            _c = "#2E7D32" if _ln.startswith("+") else "#C62828" if _ln.startswith("-") else "#8a949b"
            _out.append(f'<span style="color:{_c}">{html.escape(_ln)}</span>')
        return ('<pre style="white-space:pre-wrap;font-size:12px;line-height:1.45;margin:6px 0;padding:8px 10px;'
                'background:rgba(127,127,127,.07);border-radius:8px">' + "\n".join(_out) + "</pre>")

    _cards = [
        '<div style="font-size:13px;line-height:1.7;margin-bottom:6px"><b>一句話需求：</b>'
        + html.escape(_p["prompt"]) + "</div>"
    ]
    for _i, _row in enumerate(_rows):
        _code = V["codes"][_row[0]]
        _ok = _row[1] + _row[2] == _nb + _ne
        _badge = ("✅ 完整測試全過" if _ok else
                  f"❌ 基本 {_row[1]}/{_nb}、邊界 {_row[2]}/{_ne}") + ("（逾時）" if _row[3] else "")
        _card = (f'<div style="border:2px solid {"#55A868" if _ok else "#9AA7AE"};border-radius:12px;'
                 f'padding:10px 12px;margin:10px 0">'
                 f'<div style="font-weight:800;font-size:13.5px">第 {_i + 1} 版　{_badge}</div>'
                 f'<div style="margin:6px 0">{_dots(_row)}</div>')
        if _i > 0:
            _card += '<div style="font-size:12px;color:#8a949b">跟上一版的 diff：</div>'
            _card += _diff(V["codes"][_rows[_i - 1][0]], _code)
        _card += '<details><summary style="cursor:pointer;font-size:12.5px">看完整程式</summary>' + _pre(_code, "#4C72B0") + "</details>"
        if _row[4] >= 0:
            _card += ('<div style="font-size:12px;color:#8a949b;margin-top:6px">AI 接著收到的回饋：</div>'
                      + _pre(V["outs"][_row[4]], "#DD8452"))
        elif trace_cond.value == "reroll" and not _ok and _i + 1 < len(_rows):
            _card += '<div style="font-size:12px;color:#8a949b;margin-top:6px">（重抽：沒有回饋，開新對話再生成一次）</div>'
        _card += "</div>"
        _cards.append(_card)
    _last = _rows[-1]
    if trace_cond.value == "weak" and _last[1] == _nb and _last[2] < _ne:
        _cards.append('<div style="border-left:4px solid #C44E52;padding:8px 12px;font-size:13px;line-height:1.7">'
                      "<b>基本測試全綠，迴圈停了</b>——但空心的邊界測試還是紅的。AI 看不到的測試，它不會去修；"
                      "在它眼裡這一版已經「做完了」。</div>")
    mo.Html("<div>" + "".join(_cards) + "</div>")
    return


