@app.cell
def _(PROB, design_prob, mo):
    _p = PROB[design_prob.value]

    def _label(kind, i, args, exp):
        _call = f"{design_prob.value}({', '.join(repr(a) for a in args)})"
        _rhs = f"raise {exp['raises']}" if isinstance(exp, dict) else repr(exp)
        return f"{'基本' if kind == 'basic' else '邊界'} {i}：{_call} → {_rhs}"

    _opts = {}
    for _kind in ("basic", "edge"):
        for _i, (_args, _exp) in enumerate(_p[_kind], 1):
            _opts[_label(_kind, _i, _args, _exp)] = (_kind, _i - 1)
    _basic_only = [k for k, v in _opts.items() if v[0] == "basic"]
    design_tests = mo.ui.multiselect(options=_opts, value=_basic_only, label="你的測試集")
    design_tests
    return (design_tests,)


@app.cell
def _(PROB, V, check_one, design_prob, safe_exec):
    # 這一題所有 AI 寫過的程式（去重、排除當時跑到逾時的），逐一在瀏覽器裡重跑全部測試案例
    _p = PROB[design_prob.value]
    _cases = [("basic", i, a, e) for i, (a, e) in enumerate(_p["basic"])] + \
             [("edge", i, a, e) for i, (a, e) in enumerate(_p["edge"])]
    _ids = sorted({row[0] for t in V["tasks"] if t["p"] == design_prob.value
                   for rows in t["b"].values() for row in rows if not row[3]})
    design_results = []
    for _cid in _ids:
        _fn = safe_exec(V["codes"][_cid], design_prob.value)
        design_results.append((_cid, {(k, i): check_one(_fn, a, e) for k, i, a, e in _cases}))
    return (design_results,)


@app.cell
def _(design_results, design_tests, plt):
    _sel = list(design_tests.value)
    _acc_ok = _acc_bad = _rej = 0
    for _cid, _res in design_results:
        _all_ok = all(_res.values())
        _accepted = all(_res[s] for s in _sel)
        if _accepted and _all_ok:
            _acc_ok += 1
        elif _accepted:
            _acc_bad += 1
        else:
            _rej += 1
    _fig, _ax = plt.subplots(figsize=(6.4, 2.5))
    _left = 0
    _handles = []
    for _v, _c, _nm in [(_acc_ok, "#55A868", "passed & truly correct"),
                        (_acc_bad, "#C44E52", "passed YOUR tests but wrong"),
                        (_rej, "#9AA7AE", "caught by your tests")]:
        _h = _ax.barh([0], [_v], left=_left, color=_c, edgecolor="#1C2B33", linewidth=1, height=0.5,
                      label=f"{_nm}: {_v}")
        _handles.append(_h)
        if _v:
            _ax.text(_left + _v / 2, 0, str(_v), ha="center", va="center", color="white", fontweight="bold")
        _left += _v
    _ax.set_xlim(0, max(1, _left))
    _ax.set_yticks([])
    _ax.xaxis.set_major_locator(plt.MaxNLocator(integer=True))
    _ax.set_xlabel(f"unique AI-written programs for this problem ({_left})")
    _fig.legend(handles=_handles, fontsize=8.5, loc="lower center", ncol=1, frameon=False)
    _fig.subplots_adjust(left=0.04, right=0.97, top=0.88, bottom=0.56)
    _ax.set_title(f"your test suite: {len(_sel)} case(s)", fontsize=10)
    _fig
    return


@app.cell
def _(PROB, V, design_prob, design_results, design_tests, html, mo):
    _sel = list(design_tests.value)
    _p = PROB[design_prob.value]
    _bad = [(c, r) for c, r in design_results if all(r[s] for s in _sel) and not all(r.values())]
    if not _sel:
        _msg = "你的測試集是空的——**每一份程式都會被放行**。沒有測試，就沒有眼睛。"
        _ex = ""
    elif not _bad:
        _msg = "你的測試集沒有放行任何錯誤的程式。🎯 試試看拿掉幾個邊界案例，看破口怎麼出現。"
        _ex = ""
    else:
        _cid, _res = _bad[0]
        _missed = [k for k, v in _res.items() if not v]
        _k, _i = _missed[0]
        _args, _exp = _p[_k][_i]
        _call = f"{design_prob.value}({', '.join(repr(a) for a in _args)})"
        _want = f"raise {_exp['raises']}" if isinstance(_exp, dict) else repr(_exp)
        _msg = (f"有 **{len(_bad)} 份**錯誤的程式會被你的測試集放行。舉一份為例——它在你沒放進來的 "
                f"`{_call}` 上會出錯（應該是 `{_want}`）：")
        _ex = ('<pre style="white-space:pre-wrap;font-size:12px;line-height:1.5;padding:8px 10px;'
               'border-left:4px solid #C44E52;background:rgba(127,127,127,.07);border-radius:0 8px 8px 0">'
               + html.escape(V["codes"][_cid]) + "</pre>")
    mo.vstack([mo.md(_msg), mo.Html(_ex)])
    return


