@app.cell
def _(COND_COLOR, COND_EN, CONDS, MAXK, RUNS, V, att_at, is_pass, my_cond, my_k, np, plt):
    def _stats(c, k):
        _solved = np.zeros(RUNS)
        _tok = np.zeros(RUNS)
        _sec = np.zeros(RUNS)
        for _t in V["tasks"]:
            _rows = _t["b"][c][:k]
            _solved[_t["r"]] += is_pass(_t["p"], att_at(_rows, k))
            _tok[_t["r"]] += sum(r[6] for r in _rows)
            _sec[_t["r"]] += sum(r[5] for r in _rows)
        return _solved, _tok, _sec

    budget = {(c, k): _stats(c, k) for c in CONDS for k in range(1, MAXK + 1)}
    _fig, _ax = plt.subplots(figsize=(6.4, 3.8))
    for _c in CONDS:
        _xs = [budget[(_c, k)][1].mean() for k in range(1, MAXK + 1)]
        _ys = [budget[(_c, k)][0].mean() for k in range(1, MAXK + 1)]
        _ax.plot(_xs, _ys, "-o", color=COND_COLOR[_c], label=COND_EN[_c], linewidth=2, markersize=4)
    _s, _t2, _ = budget[(my_cond.value, my_k.value)]
    _ax.plot([_t2.mean()], [_s.mean()], "o", markersize=15, markerfacecolor="none",
             markeredgecolor="#1C2B33", markeredgewidth=2.2)
    _ax.set_xlabel("output tokens spent per run of 12 problems (mean)")
    _ax.set_ylabel("problems passing all tests (mean)")
    _ax.set_title("score vs. token budget (circle = your choice)", fontsize=10)
    _ax.grid(alpha=0.3)
    _ax.legend(fontsize=8.5, loc="lower right")
    _fig.tight_layout()
    _fig
    return (budget,)


@app.cell
def _(COND_LABEL, NPROB, budget, mo, my_cond, my_k):
    _s, _tok, _sec = budget[(my_cond.value, my_k.value)]
    _s1, _tok1, _sec1 = budget[(my_cond.value, 1)]
    _gain = _s.mean() - _s1.mean()
    _extra = _tok.mean() - _tok1.mean()
    _per = f"每多救回 1 題約花 **{_extra / _gain:,.0f}** 個輸出 token" if _gain > 0.05 else "多試的次數幾乎沒有救回任何題目"
    mo.md(
        f"""
    **{COND_LABEL[my_cond.value]}、最多試 {my_k.value} 次**：平均 **{_s.mean():.1f} / {NPROB}** 題全過
    （最少 {_s.min():.0f}、最多 {_s.max():.0f}），每輪 12 題平均花 **{_tok.mean():,.0f}** 個輸出 token、
    生成時間合計約 **{_sec.mean():.0f} 秒**。

    跟只試 1 次比：多救回 {_gain:.1f} 題，{_per}。
    """
    )
    return


